import math

def check_condition(n):
    if n < 0:
        return False

    # Check denominator
    if 2*n - 1 == 0:
        # Should not happen for non-negative integers n, as 2n-1 >= -1.
        # If n=0, 2n-1 = -1.
        return False

    try:
        # Calculate the expression
        numerator = 3 * (math.factorial(n + 2) + 1)
        denominator = 2 * n - 1

        # Check if it is an integer
        if numerator % denominator == 0:
            return True
        else:
            return False
    except OverflowError:
        # Factorial will quickly become too large for standard float/int types 
        # if n is very big, but for n=12 it should be fine.
        return False

candidates = [0, 1, 2, 4, 12]
results = {n: check_condition(n) for n in candidates}

print("Verification of candidates {0, 1, 2, 4, 12}:")
for n, is_solution in results.items():
    print(f"n={n}: {is_solution}")

import math

def check_condition(n):
    if n < 0:
        return False

    # Handle the case 2n-1 = 0, which happens if n=0.5 (not integer)
    # For n=0, 2n-1 = -1. The expression is 3*((2)!+1)/(-1) = 3*3/-1 = -9. Integer.
    if 2 * n - 1 == 0:
        return False # Should not happen for integer n >= 0

    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    return numerator % denominator == 0

solutions = []
for n in range(21, 31):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found in range 21 <= n <= 30: {solutions}")
